"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

// Button: generated by UIX from the design system. Same variants and sizes as the Figma component.

const buttonVariants = cva(
  "inline-flex shrink-0 cursor-pointer select-none items-center justify-center whitespace-nowrap transition-colors disabled:pointer-events-none disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:shrink-0 focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus rounded-md",
  {
    variants: {
      variant: {
        primary: "bg-brand text-fg-on-brand hover:bg-brand-hover active:bg-brand-pressed disabled:bg-disabled disabled:text-fg-disabled skin-solid",
        secondary: "bg-secondary text-fg-on-secondary hover:bg-secondary-hover active:bg-secondary-pressed disabled:bg-disabled disabled:text-fg-disabled skin-solid",
        soft: "bg-brand-subtle text-fg-brand hover:bg-info-subtle active:bg-muted disabled:bg-disabled disabled:text-fg-disabled",
        outline: "border border-line-default bg-surface text-fg-primary hover:bg-subtle hover:border-line-strong active:bg-muted disabled:bg-disabled disabled:text-fg-disabled",
        ghost: "text-fg-primary hover:bg-subtle active:bg-muted disabled:text-fg-disabled skin-quiet",
        destructive: "bg-danger text-fg-on-danger hover:bg-danger-hover active:bg-danger-pressed disabled:bg-disabled disabled:text-fg-disabled skin-solid",
        link: "text-fg-brand underline-offset-4 hover:underline active:underline disabled:text-fg-disabled skin-quiet",
      },
      size: {
        sm: "h-8 px-3 gap-1-5 text-label-small [&_svg]:size-4",
        md: "h-10 px-4 gap-2 text-label-medium [&_svg]:size-5",
        lg: "h-12 px-5 gap-2 text-label-large [&_svg]:size-5",
      },
    },
    compoundVariants: [
      { variant: "link", size: "sm", class: "px-0" },
      { variant: "link", size: "md", class: "px-0" },
      { variant: "link", size: "lg", class: "px-0" },
    ],
    defaultVariants: {
      variant: "primary",
      size: "md",
    },
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /** Icon before the label. */
  leadingIcon?: React.ReactNode;
  /** Icon after the label. */
  trailingIcon?: React.ReactNode;
  /** Avatar before the label (for example <Avatar size="xs" initials="AB" />). */
  avatar?: React.ReactNode;
  /** Count pill after the label. */
  badge?: React.ReactNode;
  /** Hairline between the avatar / icon and the label. */
  leadingDivider?: boolean;
  /** Hairline between the label and the badge / icon. */
  trailingDivider?: boolean;
  /** Shows a spinner before the content, dims the label and blocks clicks. */
  loading?: boolean;
  /** False hides the label visually (it stays the accessible name): an icon-only button. */
  showLabel?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, type = "button", leadingIcon, trailingIcon, avatar, badge, leadingDivider = false, trailingDivider = false, loading = false, showLabel = true, disabled, children, ...props }, ref) => (
    <button data-slot="button" data-kind="control" ref={ref} type={type} disabled={disabled || loading} aria-busy={loading || void 0} className={cn(buttonVariants({ variant, size }), className)} {...props}>
      {loading ? <span aria-hidden className="inline-block shrink-0 animate-spin rounded-full border-2 border-current border-t-transparent size-4" /> : null}
      {avatar}
      {leadingIcon}
      {leadingDivider ? <span aria-hidden className="h-4 w-px shrink-0 bg-current opacity-30" /> : null}
      {children == null ? null : showLabel ? <span className={loading ? "opacity-70" : void 0}>{children}</span> : <span className="sr-only">{children}</span>}
      {trailingDivider ? <span aria-hidden className="h-4 w-px shrink-0 bg-current opacity-30" /> : null}
      {badge != null ? <span className="inline-flex min-w-5 shrink-0 items-center justify-center rounded-full bg-current/15 px-1-5 text-label-small">{badge}</span> : null}
      {trailingIcon}
    </button>
  ),
);
Button.displayName = "Button";

export { Button, buttonVariants };
